definition.script:
pipeline {
  agent any
  options {
    timestamps()
    timeout(time: 45, unit: 'MINUTES')
    disableConcurrentBuilds()
  }
  environment {
    RUSTC_WRAPPER = 'sccache'
    SCCACHE_DIR = '/mnt/mirrorborn/shared/sccache'
    CARGO_TERM_COLOR = 'never'
  }
  stages {
    stage('Checkout exo') {
      steps {
        git branch: 'exo', url: 'https://github.com/wbic16/phext-lattice.git'
        sh 'git log -1 --format="%H %ci %s"'
      }
    }
    stage('cargo test') {
      steps {
        sh '''#!/bin/bash
set -o pipefail
sccache --start-server 2>/dev/null || true
cargo test 2>&1 | tee cargo-test-output.log
'''
      }
    }
  }
  post {
    always {
      sh 'sccache --show-stats 2>/dev/null | head -12 || true'
      archiveArtifacts artifacts: 'cargo-test-output.log', allowEmptyArchive: true
    }
  }
}
